journals.script:
{
is_shown_when_inactive = { c:MGL ?= this has_variable = ywc_v03_initialized NOT = { has_variable = ywc_t11_started } }
possible = { c:MGL ?= this ywc_v03_has_capacity = yes ywc_t11_entry_ready = yes NOT = { has_variable = ywc_t11_started } }
immediate = { set_variable = { name = ywc_t11_started value = 1 } set_variable = { name = ywc_t11_stage value = 1500 } set_variable = { name = ywc_t11_pending value = 1500 } change_variable = { name = ywc_v03_active_arc_count add = 1 } change_variable = { name = ywc_v03_visible_task_count add = 1 } }
on_monthly_pulse = { effect = {
if = { limit = { OR = { var:ywc_t11_stage ?= 1501 var:ywc_t11_stage ?= 1504 var:ywc_t11_stage ?= 1506 } NOT = { ywc_t11_partner_current = yes } } if = { limit = { var:ywc_t11_stage ?= 1501 } set_variable = { name = ywc_t11_stage value = 1502 } set_variable = { name = ywc_t11_pending value = 1502 } } else_if = { limit = { var:ywc_t11_stage ?= 1504 } set_variable = { name = ywc_t11_stage value = 1505 } set_variable = { name = ywc_t11_pending value = 1505 } } else = { set_variable = { name = ywc_t11_stage value = 1507 } set_variable = { name = ywc_t11_pending value = 1507 } set_variable = { name = ywc_t11_proposed_outcome value = 2 } } set_variable = { name = ywc_t11_partner_lost value = 1 } set_variable = { name = ywc_t11_wait_months value = 0 } change_variable = { name = ywc_t11_popup_epoch add = 1 } c:OIR ?= { remove_variable = ywc_t11_pending } }
if = { limit = { OR = { var:ywc_t11_stage ?= 1501 var:ywc_t11_stage ?= 1504 var:ywc_t11_stage ?= 1506 } } if = { limit = { NOT = { has_variable = ywc_t11_wait_months } } set_variable = { name = ywc_t11_wait_months value = 1 } } else = { change_variable = { name = ywc_t11_wait_months add = 1 } } if = { limit = { var:ywc_t11_wait_months >= 6 } set_variable = { name = ywc_t11_outcome value = 4 } set_variable = { name = ywc_t11_stage value = 1507 } remove_variable = ywc_t11_pending set_variable = { name = ywc_t11_wait_months value = 0 } change_variable = { name = ywc_t11_popup_epoch add = 1 } c:OIR ?= { remove_variable = ywc_t11_pending } } }
if = { limit = { ywc_t11_mgl_delivery_1500 = yes } trigger_event = { id = ywc_society.1500 } }
if = { limit = { ywc_t11_mgl_delivery_1502 = yes } trigger_event = { id = ywc_society.1502 } }
if = { limit = { ywc_t11_mgl_delivery_1503 = yes } trigger_event = { id = ywc_society.1503 } }
if = { limit = { ywc_t11_mgl_delivery_1505 = yes } trigger_event = { id = ywc_society.1505 } }
if = { limit = { ywc_t11_mgl_delivery_1507 = yes } trigger_event = { id = ywc_society.1507 } }
} }
on_complete = { ywc_t11_release_capacity = yes }
on_fail = { ywc_t11_release_capacity = yes }
}
